use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,collections::BTreeMap};
const R:&str="/home/ubuntu/src/zopro-perf-work/crt-euler176";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-11-05-crt-euler176";
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn copy(a:impl AsRef<Path>,b:impl AsRef<Path>){let(a,b)=(a.as_ref(),b.as_ref());fs::create_dir_all(b.parent().unwrap()).unwrap();fs::copy(a,b).unwrap();assert_eq!(hash(a),hash(b));}
fn list(p:&Path,out:&mut Vec<String>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();assert!(!e.file_type().unwrap().is_symlink());if e.file_type().unwrap().is_dir(){list(&e.path(),out)}else{assert!(e.file_type().unwrap().is_file());out.push(e.path().strip_prefix(D).unwrap().display().to_string());}}}
fn main(){
 assert!(!Path::new(D).exists());let review:Value=serde_json::from_slice(&fs::read(format!("{R}/review.json")).unwrap()).unwrap();assert_eq!(review["passed"],true);
 copy(format!("{R}/report.md"),format!("{D}/README.md"));
 for f in["Cargo.toml","Cargo.lock","src/lib.rs","src/main.rs","design.md","next-math.md","algebra.json","review.json","review.log","review.rs","prepare.rs","prepare.log","pins.json","pins-fixed.json","plan.json","plan-fixed.json","repair-toolchain.rs","repair-toolchain.log","fetch-initial.log","fetch.log","workflow.log","workflow-fixed.log","publish.rs"]{copy(format!("{R}/{f}"),format!("{D}/artifacts/{f}"));}
 for(r,steps)in[("runs",vec!["algebra-tests"]),("runs-fixed",vec!["algebra-tests","build-full-domain","full-domain-algebra"])]{
  for f in["protocol.json","source-pins.json","completed.json","progress.json","result.json","attempt-0.json"]{let src=format!("{R}/{r}/{f}");if Path::new(&src).exists(){copy(src,format!("{D}/artifacts/receipts/{r}/{f}"));}}
  for s in steps{for f in["command.json","exit.json","stdout.log","stderr.log","tests.json"]{let src=format!("{R}/{r}/{s}/{f}");if Path::new(&src).exists(){copy(src,format!("{D}/artifacts/receipts/{r}/{s}/{f}"));}}}
 }
 let meta:Value=serde_json::from_slice(&fs::read(format!("{R}/metadata.json")).unwrap()).unwrap();let pkg=meta["packages"].as_array().unwrap().iter().find(|p|p["name"]=="tfhe-ntt").unwrap();let source=Path::new(pkg["manifest_path"].as_str().unwrap()).parent().unwrap();copy(source.join("LICENSE"),format!("{D}/artifacts/TFHE-NTT-LICENSE"));
 let up=json!({"name":pkg["name"],"version":pkg["version"],"license":pkg["license"],"vcs":serde_json::from_slice::<Value>(&fs::read(source.join(".cargo_vcs_info.json")).unwrap()).unwrap(),"prime32_source_sha256":hash(source.join("src/prime32.rs")),"source_not_copied_or_altered":true,"default_features":["std","avx512"],"all_dependency_files_pinned_in":"pins-fixed.json"});fs::write(format!("{D}/artifacts/upstream.json"),serde_json::to_vec_pretty(&up).unwrap()).unwrap();
 let mut files=Vec::new();list(Path::new(D),&mut files);files.sort();let index=files.iter().map(|f|(f.clone(),json!({"sha256":hash(format!("{D}/{f}")),"bytes":fs::metadata(format!("{D}/{f}")).unwrap().len()}))).collect::<BTreeMap<_,_>>();fs::write(format!("{D}/artifact-index.json"),serde_json::to_vec_pretty(&index).unwrap()).unwrap();
 let text=fs::read_to_string(format!("{D}/README.md")).unwrap();let mut links=0;for tail in text.split("](").skip(1){let target=tail.split_once(')').unwrap().0;if target.starts_with("https://"){continue;}assert!(Path::new(D).join(target).is_file(),"missing {target}");links+=1;}
 let pubreview=json!({"passed":true,"files_before_indices":files.len(),"local_readme_links":links,"source_and_receipt_hash_copies_exact":true,"archives_created":false,"private_payloads_or_binaries_published":false,"new_proofs":0});fs::write(format!("{R}/publication-review.json"),serde_json::to_vec_pretty(&pubreview).unwrap()).unwrap();copy(format!("{R}/publication-review.json"),format!("{D}/publication-review.json"));
 files.clear();list(Path::new(D),&mut files);files.sort();let sums=files.iter().map(|f|format!("{}  {f}\n",hash(format!("{D}/{f}")))).collect::<String>();fs::write(format!("{D}/SHA256SUMS"),sums).unwrap();for(f,v)in index{assert_eq!(hash(format!("{D}/{f}")),v["sha256"].as_str().unwrap());}println!("PublicationPASS {}checksums/{}local links;exact receipts/source;no binaries/private data",files.len(),links);
}
